export type BalanceFilter={status:'all'|'Confirmed'|'In house'|'Checked out'|'Cancelled';field:'all'|'arrival'|'departure'|'undated';start:string|null;end:string|null};
export type BalanceRow={reservation_id:string;source:string;reference:string;status:string;cancellation_disposition:string|null;arrival:string|null;departure:string|null;available:boolean;unavailable_reason:string|null;opening_mode:'frozen'|'reservation_preview'|'unavailable';flags:Record<string,boolean>;context_fingerprint:string;folio_entry_count:number;charges_minor:string|null;recorded_paid_minor:string|null;balance_minor:string|null};
export type BalanceReport={schema_version:1;tenant_id:string;property_id:string;actor_id:string;role:string;property:{tenant_id:string;id:string;name:string;currency:string;time_zone:string;operating_model:string};generated_at:string;business_date:string;status_filter:string;date_filter:{field:string;start:string|null;end_exclusive:string|null};basis:string;currency:string;complete:true;rows_truncated:false;rows:BalanceRow[];summary:{reservation_count:number;known_count:number;unknown_count:number;unfrozen_count:number;amounts_complete:boolean;known_charges_minor:string;known_recorded_paid_minor:string;known_positive_balances_minor:string;known_credit_balances_minor:string;known_net_balance_minor:string};semantics:Record<string,unknown>};
const uuid=(v:unknown)=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(v);
const date=(v:unknown):v is string=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&Number.isFinite(Date.parse(v))&&new Date(v).toISOString().slice(0,10)===v;
const integer=(v:unknown,max:number)=>Number.isInteger(v)&&typeof v==='number'&&v>=0&&v<=max;
const money=(v:unknown,signed=false):v is string=>typeof v==='string'&&(signed?/^(0|-?[1-9][0-9]{0,15})$/:/^(0|[1-9][0-9]{0,15})$/).test(v)&&BigInt(v)<=BigInt('9007199254740991')&&BigInt(v)>=BigInt('-9007199254740991');
export function validateBalanceFilter(f:BalanceFilter){if(!f||!['all','Confirmed','In house','Checked out','Cancelled'].includes(f.status)||!['all','arrival','departure','undated'].includes(f.field))throw Error('Choose valid balance report filters.');if(f.field==='all'||f.field==='undated'){if(f.start!==null||f.end!==null)throw Error('Date bounds do not apply to this selection.');}else if(!date(f.start)||!date(f.end)||Date.parse(f.end)<=Date.parse(f.start)||Date.parse(f.end)-Date.parse(f.start)>366*86400000)throw Error('Choose 1 to 366 stay dates.');return f;}
export function readBalanceRegister(value:unknown,scope:{actor:string;tenant:string;property:string},filter:BalanceFilter):BalanceReport{
 validateBalanceFilter(filter);if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Guest balance report unavailable.');const r=value as BalanceReport;
 if(![scope.actor,scope.tenant,scope.property].every(uuid)||r.schema_version!==1||r.actor_id!==scope.actor||r.tenant_id!==scope.tenant||r.property_id!==scope.property||!['owner','manager'].includes(r.role)||r.currency!=='USD'||r.basis!=='current_guest_balances'||r.complete!==true||r.rows_truncated!==false)throw Error('Balance report scope or completeness does not match.');
 if(!r.property||r.property.tenant_id!==scope.tenant||r.property.id!==scope.property||r.property.currency!=='USD'||typeof r.property.name!=='string'||typeof r.property.time_zone!=='string'||!['hotel','whole_home'].includes(r.property.operating_model)||!date(r.business_date)||typeof r.generated_at!=='string'||!Number.isFinite(Date.parse(r.generated_at)))throw Error('Invalid balance report property or snapshot.');
 if(r.status_filter!==filter.status||r.date_filter?.field!==filter.field||r.date_filter.start!==filter.start||r.date_filter.end_exclusive!==filter.end)throw Error('Balance report filters changed.');
 if(!r.semantics||r.semantics.snapshot!=='current'||r.semantics.unfrozen_basis!=='current booked value'||r.semantics.date_filter_selects!=='scheduled stays, not historical balances'||['is_general_ledger','is_invoice_aging','verifies_payment_settlement','includes_security_deposits'].some(k=>r.semantics[k]!==false))throw Error('Unsupported balance report basis.');
 if(!Array.isArray(r.rows)||r.rows.length>1000||!r.summary)throw Error('Invalid balance register rows.');
 let charges=BigInt(0),paid=BigInt(0),positive=BigInt(0),credit=BigInt(0),net=BigInt(0),known=0,unknown=0,unfrozen=0,entryCount=0;const ids=new Set<string>();
 for(const row of r.rows){
  if(!row||!uuid(row.reservation_id)||ids.has(row.reservation_id)||!['direct','migration','iratepilot-ota'].includes(row.source)||typeof row.reference!=='string'||!['Confirmed','In house','Checked out','Cancelled'].includes(row.status)||(filter.status!=='all'&&row.status!==filter.status)||!(row.arrival===null||date(row.arrival))||!(row.departure===null||date(row.departure))||typeof row.available!=='boolean'||!integer(row.folio_entry_count,10000)||!['frozen','reservation_preview','unavailable'].includes(row.opening_mode))throw Error('Invalid or repeated balance row.');ids.add(row.reservation_id);entryCount+=row.folio_entry_count;
  const selectedDate=filter.field==='arrival'?row.arrival:row.departure;
  if((filter.field==='arrival'||filter.field==='departure')&&(!selectedDate||selectedDate<filter.start!||selectedDate>=filter.end!))throw Error('Balance row is outside the selected stays.');if(filter.field==='undated'&&row.arrival!==null&&row.departure!==null)throw Error('Dated stay in undated report.');
  if(!row.flags||Object.keys(row.flags).sort().join(',')!=='current_pricing_reconciliation_required,opening_pricing_reconciliation_required,pricing_reconciliation_required,reservation_amounts_changed'||Object.values(row.flags).some(v=>typeof v!=='boolean')||row.flags.pricing_reconciliation_required!==(row.flags.reservation_amounts_changed||row.flags.opening_pricing_reconciliation_required||row.flags.current_pricing_reconciliation_required)||typeof row.context_fingerprint!=='string'||!/^[0-9a-f]{64}$/.test(row.context_fingerprint))throw Error('Invalid balance reconciliation details.');
  if(row.opening_mode!=='frozen'){unfrozen++;if(row.folio_entry_count!==0)throw Error('Unfrozen balance has recorded entries.');}
  if(row.available){if(row.unavailable_reason!==null||row.opening_mode==='unavailable'||!money(row.charges_minor)||!money(row.recorded_paid_minor)||!money(row.balance_minor,true))throw Error('Known balance amounts unavailable.');const c=BigInt(row.charges_minor),p=BigInt(row.recorded_paid_minor),b=BigInt(row.balance_minor);if(c-p!==b)throw Error('Guest balance does not reconcile.');known++;charges+=c;paid+=p;net+=b;if(b>0)positive+=b;else credit-=b;}
  else{unknown++;if(row.opening_mode!=='unavailable'||row.unavailable_reason!=='reservation_charges_unavailable'||row.charges_minor!==null||row.recorded_paid_minor!==null||row.balance_minor!==null)throw Error('Unknown balance must not contain invented amounts.');}
 }
 const s=r.summary;if(entryCount>10000||s.reservation_count!==r.rows.length||s.known_count!==known||s.unknown_count!==unknown||s.unfrozen_count!==unfrozen||s.amounts_complete!==(unknown===0)||s.known_charges_minor!==charges.toString()||s.known_recorded_paid_minor!==paid.toString()||s.known_positive_balances_minor!==positive.toString()||s.known_credit_balances_minor!==credit.toString()||s.known_net_balance_minor!==net.toString())throw Error('Balance report totals do not match its complete rows.');return r;
}

export function balanceDecimal(value:string|null){if(value===null)return '';const n=BigInt(value),absolute=n<0?-n:n;return (n<0?'-':'')+(absolute/BigInt(100)).toString()+'.'+(absolute%BigInt(100)).toString().padStart(2,'0');}
export function balanceCollectionReview(row:BalanceRow):string{
 const notes:string[]=[];
 if(!row.available)notes.push('Charges unavailable');
 if(row.flags.pricing_reconciliation_required)notes.push('Pricing reconciliation required');
 if(row.status==='Cancelled'&&row.opening_mode==='reservation_preview')notes.push('Review cancellation charges before collection; amount is booked value');
 if(row.source==='migration')notes.push('Review migrated account for opening receivables and unapplied prepayments');
 return notes.join('; ');
}
export function balanceRegisterRows(r:BalanceReport):(string|number|boolean)[][]{
 return [
 ['Report','Current guest balances'],['Property',r.property.name],['Property reference',r.property_id],['Generated at',r.generated_at],['Business date',r.business_date],['Currency','USD'],['Reservation status',r.status_filter],['Stay date selection',r.date_filter.field],['From',r.date_filter.start??''],['Until (exclusive)',r.date_filter.end_exclusive??''],['Basis','Current balances; dates select scheduled stays, not historical balances. Unfrozen openings use current booked value.'],['Exclusions','Not general ledger, invoice aging, settlement verification or security deposits.'],['Unknown amount stays',r.summary.unknown_count],['Known positive balances USD',balanceDecimal(r.summary.known_positive_balances_minor)],['Known credits USD',balanceDecimal(r.summary.known_credit_balances_minor)],['Known net balance USD',balanceDecimal(r.summary.known_net_balance_minor)],[],
 ['Reservation','Reference','Source','Status','Arrival','Departure','Amount available','Opening basis','Charges USD','Recorded paid USD','Balance USD','Pricing reconciliation required','Unavailable reason','Collection review'],
 ...r.rows.map(row=>[row.reservation_id,row.reference,row.source,row.cancellation_disposition==='no_show'?'No show':row.status,row.arrival??'',row.departure??'',row.available,row.opening_mode,balanceDecimal(row.charges_minor),balanceDecimal(row.recorded_paid_minor),balanceDecimal(row.balance_minor),row.flags.pricing_reconciliation_required,row.unavailable_reason??'',balanceCollectionReview(row)])];
}
